def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue

            # Find each 4-connected foreground component and its marker color.
            stack = [(r, c)]
            seen[r][c] = True
            component = []
            colors = set()
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                if grid[y][x] not in (0, 1):
                    colors.add(grid[y][x])
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                            grid[yy][xx] != 0 and not seen[yy][xx]):
                        seen[yy][xx] = True
                        stack.append((yy, xx))

            if not colors:
                continue
            color = min(colors)
            members = set(component)

            # Recolor the component's interior: cells surrounded in all
            # eight directions by foreground belonging to this component.
            for y, x in component:
                if grid[y][x] != 1:
                    continue
                if all((y + dy, x + dx) in members
                       for dy in (-1, 0, 1)
                       for dx in (-1, 0, 1)
                       if dy or dx):
                    out[y][x] = color

    return out
